// The VDX default bank (SPEC §15.3), embedded from core/sysex/default_bank.inc
// (generated by tools/make_default_bank.py from banks/default/*.json).
#pragma once

#include <cstdint>

namespace vdx::sysex {

// The 4104-byte bank dump, byte-identical to banks/vdx-default.syx.
const uint8_t* defaultBankSyx();
// The 4096 packed voice bytes inside it (slot k at offset (k - 1) * 128).
const uint8_t* defaultBankPacked();

}  // namespace vdx::sysex
